<?php
require_once __DIR__ . '/../config/auth.php'; exigirPerfil(['Cliente']); require_once __DIR__ . '/../config/conexao.php';
$uid=(int)$_SESSION['usuario_id']; $st=$conn->prepare('SELECT id,titulo,descricao,prioridade,status,resposta,criado_em,tipo_equipamento,marca,modelo,numero_serie,estado_fisico,acessorios FROM chamados_cliente WHERE usuario_id=? ORDER BY criado_em DESC'); $st->bind_param('i',$uid); $st->execute(); $rs=$st->get_result(); $rows=[];$abertos=0;$resolvidos=0;
while($r=$rs->fetch_assoc()){ $rows[]=$r; if(in_array($r['status'],['Aberto','Em atendimento','Aguardando cliente']))$abertos++; if($r['status']==='Resolvido')$resolvidos++; }
?>
