<?php else: foreach($rows as $c):?><article class="ticket"><div class="ticket-top"><div><h3>#<?= (int)$c['id']?> · <?=h($c['titulo'])?></h3><p>Aberto em <?=date('d/m/Y H:i',strtotime($c['criado_em']))?> · Prioridade: <?=h($c['prioridade'])?></p></div><span class="status <?= $c['status']==='Resolvido'?'resolvido':($c['status']==='Cancelado'?'cancelado':'')?>"><?=h($c['status'])?></span></div><p><strong>Equipamento:</strong> <?=h(trim(($c['tipo_equipamento']??'').' '.($c['marca']??'').' '.($c['modelo']??'')))?></p><?php if(!empty($c['numero_serie'])):?><p><strong>Nº de série:</strong> <?=h($c['numero_serie'])?></p><?php endif;?><?php if(!empty($c['estado_fisico'])):?><p><strong>Estado físico:</strong> <?=nl2br(h($c['estado_fisico']))?></p><?php endif;?><?php if(!empty($c['acessorios'])):?><p><strong>Acessórios:</strong> <?=h($c['acessorios'])?></p><?php endif;?><p><strong>Problema relatado:</strong><br><?=nl2br(h($c['descricao']))?></p><?php if(trim((string)$c['resposta'])!==''):?><p><strong>Resposta da equipe:</strong> <?=nl2br(h($c['resposta']))?></p><?php endif;?></article><?php endforeach; endif;?></section></main></body></html>
